func MarshalSearchMetadata(v *SearchMetadata) ([]byte, error) {
	// The encoding is built in a pooled buffer and copied out once,
	// rather than written into a buffer allocated at the right size:
	// a fresh allocation is handed out zeroed, so writing into it
	// walks cold memory twice, while the copy out of a warm pooled
	// buffer allocates without zeroing and moves the bytes once.
	buf := odjsonrt.GetBuffer()
	var err error
	buf.B, err = v.odjsonAppend(buf.B, odjsonrt.ModeV2HTML)
	if err != nil {
		odjsonrt.PutBuffer(buf)
		return nil, err
	}
	out := bytes.Clone(buf.B)
	odjsonrt.PutBuffer(buf)
	return out, nil
}

// AppendSearchMetadata appends the JSON encoding of v to dst and returns the
// extended buffer. On failure dst is returned with nothing appended.
func AppendSearchMetadata(dst []byte, v *SearchMetadata) ([]byte, error) {
	n := len(dst)
	dst, err := v.odjsonAppend(dst, odjsonrt.ModeV2HTML)
	if err != nil {
		return dst[:n], err
	}
	return dst, nil
}

// UnmarshalSearchMetadata decodes a complete JSON document into v under
// encoding/json/v2's semantics. Nobody has validated data, so the parser
// rejects what jsontext would have.
func UnmarshalSearchMetadata(data []byte, v *SearchMetadata) error {
	// The cache plays the part of encoding/json/v2's string cache: a
	// value that recurs in the document is allocated once.
	sc := odjsonrt.GetStringCache()
	p, err := v.odjsonParseV2(data, odjsonrt.SkipSpace(data, 0), sc, true)
	odjsonrt.PutStringCache(sc)
	if err != nil {
		return err
	}
	return odjsonrt.EndOfDocument(data, p)
}
